/**
 * The wrapper skipping shared by the scanners (_TMB_CMD_UNWRAP_AWK in
 * cmd-analysis.sh): VAR=value words and sudo / env / command / nohup / time /
 * exec with their own options, each wrapper by its own option table. The TS
 * analyzer also skips timeout (and its duration), stdbuf and nice, and their
 * Homebrew coreutils names gtimeout, gstdbuf and gnice, which the .sh does not
 * (GH 1692). A `command -v` / `-V` lookup runs nothing, so the TS stops at its
 * option word instead of skipping to the name it looks up (GH 1872).
 */

interface WrapSpec {
  short: string;
  dirShort: string;
  long: string;
  dirLong: string;
}

const NO_SPEC: WrapSpec = { short: '', dirShort: '', long: ' ', dirLong: ' ' };

const SPECS: Record<string, WrapSpec> = {
  sudo: {
    short: 'CDRTUcghprtu',
    dirShort: 'D',
    long: ' chdir chroot close-from command-timeout group host login-class other-user prompt role type user ',
    dirLong: ' chdir ',
  },
  env: { short: 'CPSu', dirShort: 'C', long: ' chdir split-string unset ', dirLong: ' chdir ' },
  time: { short: 'fo', dirShort: '', long: ' format output ', dirLong: ' ' },
  exec: { short: 'a', dirShort: '', long: ' ', dirLong: ' ' },
  timeout: { short: 'ks', dirShort: '', long: ' kill-after signal ', dirLong: ' ' },
  stdbuf: { short: 'eio', dirShort: '', long: ' error input output ', dirLong: ' ' },
  nice: { short: 'n', dirShort: '', long: ' adjustment ', dirLong: ' ' },
};
SPECS.gtimeout = SPECS.timeout;
SPECS.gstdbuf = SPECS.stdbuf;
SPECS.gnice = SPECS.nice;

export const WRAPPER = /^(sudo|env|command|nohup|time|exec|g?timeout|g?stdbuf|g?nice)$/;
export const ASSIGNMENT = /^[A-Za-z_][A-Za-z0-9_]*=/;

/** <b> under dir <a>, as written: an absolute, ~ or $ path stands alone. */
export function under(a: string, b: string): string {
  if (a === '' || /^[/~$]/.test(b)) return b;
  if (b === '.') return a;
  return `${a}/${b}`;
}

/** awk split(s, w, /[ \t]+/), 0-based. */
export function splitWords(s: string): string[] {
  return s === '' ? [] : s.split(/[ \t]+/);
}

/** `command` at index k only prints how a name resolves: an option word holding v or V comes before any `--` or operand. */
function lookup(w: readonly string[], k: number): boolean {
  for (let j = k + 1; j < w.length && w[j].startsWith('-') && w[j] !== '--' && w[j] !== '-'; j++) {
    if (/^-[^-]*[vV]/.test(w[j])) return true;
  }
  return false;
}

/**
 * From index k of w, the index of the real argv0 (a `command -v` lookup's
 * option word) and the dirs the skipped wrappers run it in (env -C / --chdir,
 * sudo -D / --chdir, a `--chdir=<dir>` word).
 */
export function unwrap(w: readonly string[], k: number): { k: number; dirs: string[] } {
  const dirs: string[] = [];
  const n = w.length;
  while (k < n) {
    const a = w[k];
    if (a === '' || ASSIGNMENT.test(a)) {
      k++;
      continue;
    }
    if (/^--chdir=./.test(a)) {
      dirs.push(a.slice(8));
      k++;
      continue;
    }
    if (!WRAPPER.test(a)) break;
    if (a === 'command' && lookup(w, k)) return { k: k + 1, dirs };
    const spec = SPECS[a] ?? NO_SPEC;
    k++;
    while (k < n && w[k].startsWith('-')) {
      const opt = w[k];
      k++;
      if (opt === '--') break;
      if (opt === '-') continue;
      if (opt.startsWith('--')) {
        let name = opt.slice(2);
        let value = '';
        const eq = name.indexOf('=');
        if (eq >= 0) {
          value = name.slice(eq + 1);
          name = name.slice(0, eq);
        }
        if (!spec.long.includes(` ${name} `)) continue;
        if (eq < 0) {
          value = w[k] ?? '';
          k++;
        }
        if (spec.dirLong.includes(` ${name} `) && value !== '') dirs.push(value);
        continue;
      }
      for (let j = 1; j < opt.length; j++) {
        const ch = opt[j];
        if (!spec.short.includes(ch)) continue;
        let value = opt.slice(j + 1);
        if (value === '') {
          value = w[k] ?? '';
          k++;
        }
        if (spec.dirShort.includes(ch) && value !== '') dirs.push(value);
        break;
      }
    }
    if ((a === 'timeout' || a === 'gtimeout') && k < n) k++;
  }
  return { k, dirs };
}
